# -*- coding: utf-8 -*-
"""
사업 추진계획서 기반 합성 데이터.
정부 표준 사업계획서 9개 섹션(개요/배경/목표/세부계획/일정/추진체계/예산/기대효과/사후관리)을
필드로 매핑. 주관부서 1곳 + 협력부서 여러 곳이 협업하는 구조를 반영.
목적: 신임 담당자가 전임자의 사업 추진 방식(특히 부서간 협업 노하우)을 검색해서 참고.
- 부서 코드(01~08)는 DB DEPARTMENT 코드와 동일: 01 교통, 02 주택·건축, 03 환경, 04 복지,
  05 안전, 06 경제·산업, 07 문화·체육·관광, 08 행정·일반.
- domain_code는 lead_department_code와 1:1 매핑.
- task_id는 부서별로 1~30을 반복 사용(부서 구분은 lead_department_code로 함). 전체 8개 부서 x 30건 = 240건.
- status_code는 전부 "완료"로 통일(검색 대상은 완료 사업만이므로 시드 데이터 전체를 검색 가능하게 함).
  year는 사업 완료연도 기준 2023~2026 분포.
"""

